"""Resilient in-memory Three.js route viewer for Streamlit."""
from __future__ import annotations
import base64
import json
from pathlib import Path
from typing import Any, Iterable
import streamlit.components.v1 as components

MODEL_DIR = Path(__file__).resolve().parent / "assets" / "models"
MODEL_FILES = {"air": "Airplane.glb", "ocean": "Container Ship.glb", "land": "Cargo Truck.glb", "container": "Shipping Container.glb"}

def _model_base64(filename: str) -> str | None:
    path = MODEL_DIR / filename
    return base64.b64encode(path.read_bytes()).decode("ascii") if path.exists() else None

def render_route_viewer(trajectory: Iterable[Any], height: int = 560) -> None:
    """Render immediately; parsed GLBs replace animated fallback meshes when ready."""
    legs = []
    for step in trajectory:
        raw = step.model_dump() if hasattr(step, "model_dump") else (step.dict() if hasattr(step, "dict") else step)
        legs.append({"action": int(raw["action"]), "days": float(raw["days_passed"]), "label": raw["action_name"], "mode": raw.get("transport_mode", "")})
    payload = json.dumps({"legs": legs, "models": {kind: _model_base64(name) for kind, name in MODEL_FILES.items()}}).replace("</", "<\\/")
    html = f'''<!doctype html><html><head><style>
html,body{{margin:0;background:#070b14;color:#dbeafe;font-family:Inter,system-ui,sans-serif}}#viewer{{height:540px;width:100%;position:relative;overflow:hidden;background:#070b14}}canvas{{width:100%;height:100%;display:block}}#hud{{position:absolute;z-index:2;top:14px;left:14px;padding:10px 13px;border:1px solid #253758;border-radius:10px;background:#091323d9;font-size:12px;max-width:430px}}#status{{color:#9fb5d6}}#controls{{position:absolute;z-index:2;right:14px;bottom:14px;display:flex;gap:7px;flex-wrap:wrap;justify-content:flex-end}}button{{cursor:pointer;border:1px solid #2d4772;border-radius:8px;background:#10213d;color:#dbeafe;padding:8px 10px;font-weight:600}}button:hover{{background:#19345d}}
</style></head><body><div id="viewer"><div id="hud"><b>LIVE ROUTE DIGITAL TWIN</b><br><span id="status">Preparing transport assets…</span></div><div id="controls"><button id="play">Pause</button><button id="replay">Replay</button><button id="next">Step next</button><button data-cam="overview">Overview</button><button data-cam="follow">Follow</button></div></div><script type="module">
import * as THREE from 'https://esm.sh/three@0.169.0';
import {{ OrbitControls }} from 'https://esm.sh/three@0.169.0/examples/jsm/controls/OrbitControls.js';
import {{ GLTFLoader }} from 'https://esm.sh/three@0.169.0/examples/jsm/loaders/GLTFLoader.js';
import {{ RoomEnvironment }} from 'https://esm.sh/three@0.169.0/examples/jsm/environments/RoomEnvironment.js';
const data={payload},host=document.querySelector('#viewer'),status=document.querySelector('#status');
const scene=new THREE.Scene();scene.background=new THREE.Color(0x070b14);scene.fog=new THREE.Fog(0x070b14,45,100);const renderer=new THREE.WebGLRenderer({{antialias:true}});renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.setSize(host.clientWidth,host.clientHeight);renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.15;host.prepend(renderer.domElement);const camera=new THREE.PerspectiveCamera(46,host.clientWidth/host.clientHeight,.1,300);camera.position.set(20,22,31);const controls=new OrbitControls(camera,renderer.domElement);controls.target.set(0,2,0);controls.enableDamping=true;const pmrem=new THREE.PMREMGenerator(renderer);scene.environment=pmrem.fromScene(new RoomEnvironment(),.04).texture;pmrem.dispose();scene.add(new THREE.HemisphereLight(0xaad7ff,0x111827,2.1));const sun=new THREE.DirectionalLight(0xffffff,3.2);sun.position.set(12,20,8);scene.add(sun);const grid=new THREE.GridHelper(80,24,0x1e3a5f,0x10223c);grid.position.y=-.02;scene.add(grid);
const nodes=[new THREE.Vector3(-18,0,0),new THREE.Vector3(0,0,0),new THREE.Vector3(18,0,0)],labels=['Dubai Origin','Regional Checkpoint','Disaster Site'];nodes.forEach((p,i)=>{{const marker=new THREE.Mesh(new THREE.CylinderGeometry(.5,.5,.18,24),new THREE.MeshStandardMaterial({{color:[0x22d3ee,0xfbbf24,0x34d399][i],emissive:[0x083344,0x422006,0x052e16][i]}}));marker.position.copy(p);marker.position.y=.09;scene.add(marker);const c=document.createElement('canvas');c.width=360;c.height=70;const x=c.getContext('2d');x.fillStyle='#dbeafe';x.font='bold 28px Arial';x.fillText(labels[i],8,39);const sprite=new THREE.Sprite(new THREE.SpriteMaterial({{map:new THREE.CanvasTexture(c),transparent:true}}));sprite.scale.set(7.2,1.4,1);sprite.position.copy(p).add(new THREE.Vector3(0,2,0));scene.add(sprite)}});
function route(kind,from,to){{const a=nodes[from],b=nodes[to],mid=a.clone().lerp(b,.5);if(kind==='air')mid.y=10;if(kind==='ocean')mid.z=3;if(kind==='land')mid.z=-3;return new THREE.CatmullRomCurve3([a,mid,b],false,'catmullrom',.35)}}
function fallback(kind){{const colors={{air:0x38bdf8,ocean:0x0ea5e9,land:0xf59e0b}},g=new THREE.Group(),mat=new THREE.MeshStandardMaterial({{color:colors[kind],metalness:.35,roughness:.3}});if(kind==='air'){{const cone=new THREE.Mesh(new THREE.ConeGeometry(.55,3.4,12),mat);cone.rotation.z=-Math.PI/2;g.add(cone);g.add(new THREE.Mesh(new THREE.BoxGeometry(2.5,.12,.8),mat))}}else if(kind==='ocean'){{g.add(new THREE.Mesh(new THREE.BoxGeometry(3.6,.75,1.25),mat));const deck=new THREE.Mesh(new THREE.BoxGeometry(1.5,.6,.8),mat);deck.position.y=.65;g.add(deck)}}else{{g.add(new THREE.Mesh(new THREE.BoxGeometry(2.5,.65,1.1),mat));const cab=new THREE.Mesh(new THREE.BoxGeometry(.8,.65,1.05),mat);cab.position.set(1.25,.55,0);g.add(cab)}}return g}}
const rotation={{air:Math.PI/2,ocean:Math.PI/2,land:Math.PI/2}},vehicles={{}};['air','ocean','land'].forEach(kind=>{{const heading=new THREE.Group();heading.add(fallback(kind));heading.visible=false;scene.add(heading);vehicles[kind]=heading}});function kindFor(leg){{if(leg.action===0||leg.action===3)return'air';if(leg.action===2||leg.mode.toLowerCase().includes('land'))return'land';return'ocean'}}function endpoints(action){{return action===0?[0,2]:action===1||action===2?[0,1]:[1,2]}}
let index=0,progress=0,playing=true,last=performance.now(),active=null;function setLeg(i){{Object.values(vehicles).forEach(v=>v.visible=false);if(i>=data.legs.length){{active=null;status.style.display='';status.textContent='Delivery complete';return}}const leg=data.legs[i],kind=kindFor(leg);active={{kind,curve:route(kind,...endpoints(leg.action)),model:vehicles[kind]}};active.model.visible=true}}function advance(){{index++;progress=0;setLeg(index)}}setLeg(0);function animate(now){{requestAnimationFrame(animate);const dt=Math.min((now-last)/1000,.05);last=now;if(playing&&active){{progress+=dt*.16;if(progress>=1)advance();if(active){{const t=Math.min(progress,.999),p=active.curve.getPointAt(t),tangent=active.curve.getTangentAt(t);active.model.position.copy(p);active.model.rotation.y=Math.atan2(tangent.x,tangent.z)+rotation[active.kind]}}}}controls.update();renderer.render(scene,camera)}}requestAnimationFrame(animate);
function base64ToArrayBuffer(b64){{const binary=atob(b64),bytes=new Uint8Array(binary.length);for(let i=0;i<binary.length;i++)bytes[i]=binary.charCodeAt(i);return bytes.buffer}}const loader=new GLTFLoader();async function parseModel(kind){{if(!data.models[kind])throw new Error(`Missing asset: ${{kind}}`);const gltf=await new Promise((resolve,reject)=>loader.parse(base64ToArrayBuffer(data.models[kind]),'',resolve,reject));const inner=gltf.scene;inner.traverse(o=>{{if(o.isMesh){{if(!o.geometry.getAttribute('color'))o.material.vertexColors=false;if(o.material.map)o.material.map.colorSpace=THREE.SRGBColorSpace}}}});const box=new THREE.Box3().setFromObject(inner),size=box.getSize(new THREE.Vector3()),scale=(kind==='air'?4.4:kind==='ocean'?3.5:2.7)/Math.max(size.x,size.y,size.z);inner.scale.setScalar(scale);const fixed=new THREE.Box3().setFromObject(inner);inner.position.x-=(fixed.min.x+fixed.max.x)/2;inner.position.z-=(fixed.min.z+fixed.max.z)/2;inner.position.y-=fixed.min.y;const vehicle=vehicles[kind];if(vehicle){{vehicle.clear();vehicle.add(inner)}}}}
(async()=>{{const errors=[];for(const kind of ['air','ocean','land','container']){{try{{await parseModel(kind)}}catch(err){{const message=err instanceof Error?err.message:String(err);console.error(`GLB parse failure (${{kind}}):`,err);errors.push(`${{kind}}: ${{message}}`)}}}}if(errors.length){{status.style.display='';status.textContent=`GLB fallback active — ${{errors.join(' | ')}}`}}else status.style.display='none'}})();document.querySelector('#play').onclick=e=>{{playing=!playing;e.target.textContent=playing?'Pause':'Play'}};document.querySelector('#replay').onclick=()=>{{index=0;progress=0;setLeg(0)}};document.querySelector('#next').onclick=advance;document.querySelectorAll('[data-cam]').forEach(b=>b.onclick=()=>{{camera.position.set(...(b.dataset.cam==='overview'?[20,22,31]:[0,8,22]));controls.target.set(0,2,0);controls.update()}});addEventListener('resize',()=>{{camera.aspect=host.clientWidth/host.clientHeight;camera.updateProjectionMatrix();renderer.setSize(host.clientWidth,host.clientHeight)}});
</script></body></html>'''
    components.html(html, height=height, scrolling=False)
